if((page==="bo-inbox"&&!canArea("bo.decidir"))||(page==="ouvidoria-inbox"&&!canArea("ouvidoria.decidir")))html=html.replace(/<div class='support-decision-actions'>[\s\S]*?<\/div>/g,"<p class='hint'>Sua patente ainda não decide estes pedidos.</p>");
