var roster=(snap.roster||[]).slice().sort(function(a,b){return String(a.qra).localeCompare(String(b.qra),"pt-BR")}),linked=roster.find(function(r){return r.id===x.roster_id});
var link=manageAccess?"<span class='tag-grant'><select aria-label='Ficha do efetivo de "+esc(x.display_name||"integrante")+"' data-roster-select='"+esc(x.user_id)+"'><option value=''>Sem ficha do efetivo</option>"+roster.map(function(r){return"<option value='"+esc(r.id)+"'"+(r.id===x.roster_id?" selected":"")+">"+esc(r.qra+" · "+r.full_name+" · "+r.rank)+"</option>"}).join("")+"</select><button type='button' data-a='officer-link' data-id='"+esc(x.user_id)+"'>Vincular</button></span>":(linked?"<span class='hint'>Ficha: "+esc(linked.qra+" · "+linked.rank)+"</span>":"");
