var suspended=x.suspended_until&&new Date(x.suspended_until)>new Date(),status="<div class='officer-rank'><span class='tag officer-id"+(x.login_id?"":" is-missing")+"'>"+(x.login_id?"ID "+esc(x.login_id):"Sem ID")+"</span>"+(linked?rankInsigniaSvg(linked.rank)+"<b>"+esc(linked.rank)+"</b>":"<b>Visitante</b><small>sem ficha do efetivo</small>")+(suspended?"<span class='tag red'>Suspenso até "+esc(adminDate(x.suspended_until))+"</span>":"")+"</div>"+(suspended&&x.suspension_reason?"<small class='hint'>Motivo: "+esc(x.suspension_reason)+(x.suspended_by?" · por "+esc(x.suspended_by):"")+"</small>":"");
