var loginPrefill=null,RECEPTION_KEY="rota-recepcao-bilhete",receptionMode="",receptionTimer=null,receptionUnsub=null,receptionRoom=null,receptionDesk=null,receptionError="",receptionPicked=null,receptionPrev=null;
function receptionTicket(){try{return localStorage.getItem(RECEPTION_KEY)||""}catch(_){return""}}
function setReceptionTicket(v){try{if(v)localStorage.setItem(RECEPTION_KEY,v);else localStorage.removeItem(RECEPTION_KEY)}catch(_){}}
function isVisitorAccount(){try{return !previewRole&&!!window.ROTA_TICKETS&&window.ROTA_TICKETS.isVisitor()}catch(_){return false}}
function canDesk(){return previewRole==="admin"||can("acessos.gerenciar")}
function receptionPendingCount(){var q=receptionDesk?receptionDesk.queue:((adminSnapshot&&adminSnapshot.requests)||[]).filter(function(x){return x.request_type==="acesso"&&(x.status==="Pendente"||x.status==="Em atendimento")});return q.length||""}
function waited(m){return m<1?"agora há pouco":m===1?"há 1 min":m<60?"há "+m+" min":"há "+Math.floor(m/60)+" h "+(m%60)+" min"}
function presence(on){return"<span class='rc-presence"+(on?" is-on":"")+"'>"+(on?"online":"offline")+"</span>"}
function rcStatus(s){var map={"Pendente":["Aguardando","is-wait"],"Em atendimento":["Em atendimento","is-active"],"Aprovado":["Aprovado","is-ok"],"Recusado":["Recusado","is-no"],"Desistiu":["Saiu da fila","is-off"]},x=map[s]||[s,""];return"<span class='rc-status "+x[1]+"'>"+esc(x[0])+"</span>"}
// Liga e desliga a atualização (tempo real + a cada 15 s) conforme a página aberta.
function syncReception(p){var mode=p==="recepcao"?"room":p==="recepcao-balcao"?"desk":"";if(mode===receptionMode)return;receptionMode=mode;if(mode!=="desk")receptionDesk=null;if(receptionTimer)clearInterval(receptionTimer);receptionTimer=null;if(receptionUnsub){receptionUnsub();receptionUnsub=null}if(!mode||previewRole)return;setTimeout(refreshReception,0);receptionTimer=setInterval(refreshReception,15000);receptionUnsub=window.ROTA_TICKETS.onReception(function(kind){if(kind==="fila")refreshReception();else paintReception()})}
async function refreshReception(){try{if(receptionMode==="room"){var t=receptionTicket();receptionRoom=await window.ROTA_TICKETS.receptionCall("room",t?{ticket:t}:{},false);receptionError=""}else if(receptionMode==="desk"){receptionDesk=await window.ROTA_TICKETS.receptionCall("staff-queue",{},true);receptionError=""}}catch(err){receptionError=err.message;if(receptionMode==="room"&&/fila de novo/.test(err.message)){setReceptionTicket("");receptionRoom=null;render();return}}paintReception()}
function paintReception(){var box=document.getElementById("reception-live");if(!box)return;box.innerHTML=receptionMode==="desk"?deskLiveHtml():roomLiveHtml();announceReception()}
function announceReception(){var me=receptionRoom&&receptionRoom.me,live=document.getElementById("reception-announce");if(!me||!live){receptionPrev=me||null;return}var p=receptionPrev,msg="";if(p){if(p.status!==me.status)msg={"Em atendimento":"Um policial começou a te atender: "+me.attendedBy+".","Aprovado":"Seu acesso foi aprovado.","Recusado":"Seu pedido foi recusado.","Desistiu":"Você saiu da fila.","Pendente":"Você voltou a aguardar na fila."}[me.status]||"";else if(me.position&&p.position&&me.position<p.position)msg="Você subiu para a posição "+me.position+"."}receptionPrev=me;if(msg){live.textContent=msg;var t=document.querySelector(".rc-ticket");if(t){t.classList.remove("is-changed");void t.offsetWidth;t.classList.add("is-changed")}}}
function liveTag(){var on=window.ROTA_TICKETS&&window.ROTA_TICKETS.receptionLive();return"<span class='rc-live"+(on?" is-on":"")+"'>"+(on?"Ao vivo":"Atualiza a cada 15 s")+"</span>"}
function deskPanel(staff){var on=(staff||[]).filter(function(s){return s.online}).length;return"<aside class='panel rc-desk' aria-label='Responsáveis no balcão'><div class='panelhead'><div><small class='kicker'>BALCÃO</small><h2>Quem libera acesso</h2></div><span class='rc-count'>"+on+" online</span></div>"+((staff||[]).length?"<ul class='rc-staff'>"+staff.map(function(s){return"<li class='"+(s.online?"is-on":"")+"'>"+"<span class='rc-staff-id'>"+memberIdentity(s,{size:"sm"})+"</span>"+presence(s.online)+"<small class='rc-can'>"+(s.canGrantRank?"Libera visitante e integrante":"Libera visitante")+"</small></li>"}).join("")+"</ul>":"<p class='rc-empty'>Ninguém com autorização para liberar acesso ainda.</p>")+"<p class='hint rc-desk-note'>Só policiais com o poder de liberar acesso aparecem aqui. Patente só pode ser dada por quem tem o poder de promover.</p></aside>"}
