async function checkPublicApplicationCooldown(input){if(previewRole)return;var form=input&&input.form;if(!form||!input.value.trim())return;var feedback=form.querySelector('[data-apply-feedback]'),button=form.querySelector("button[type='submit']"),playerId=input.value.trim();if(feedback)feedback.textContent='Consultando o prazo pelo ID/passaporte MTA…';try{var status=await window.ROTA_TICKETS.checkApplicationCooldown(playerId);if(input.value.trim()!==playerId)return;if(status.canApply){if(feedback)feedback.textContent='ID liberado para inscrição.';if(button)button.disabled=false;return}var when=status.availableAt?new Date(status.availableAt):new Date(Date.now()+(Number(status.remainingSeconds)||0)*1000),formatted=when.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'});if(feedback)feedback.textContent='Este ID já enviou uma inscrição. Você poderá enviar outra após '+formatted+'.';if(button)button.disabled=true;var wait=Math.max(0,Number(status.remainingSeconds)||0)*1000+1000;if(wait>0&&wait<2147480000)window.setTimeout(function(){if(input.isConnected&&input.value.trim()===playerId)checkPublicApplicationCooldown(input)},wait)}catch(error){if(input.value.trim()!==playerId)return;if(feedback)feedback.textContent='Não foi possível consultar agora. O servidor verificará o prazo ao enviar.';if(button)button.disabled=false}}
